using SchoolERP.Domain.Common;using SchoolERP.Domain.Exceptions;using SchoolERP.Domain.Interfaces;namespace SchoolERP.Domain.Entities;public sealed class ClassSubject:AuditableEntity,ITenantEntity,IAggregateRoot{private ClassSubject(){}public Guid TenantId{get;private set;}public Guid SchoolId{get;private set;}public Guid AcademicYearId{get;private set;}public Guid SchoolClassId{get;private set;}public Guid SubjectId{get;private set;}public bool IsMandatory{get;private set;}public int DisplayOrder{get;private set;}public SchoolClass SchoolClass{get;private set;}=null!;public Subject Subject{get;private set;}=null!;public School School{get;private set;}=null!;public AcademicYear AcademicYear{get;private set;}=null!;Guid ITenantEntity.TenantId{get=>TenantId;set{if(TenantId!=Guid.Empty&&TenantId!=value)throw new DomainException("ClassSubject tenant cannot change.");TenantId=value;}}public static ClassSubject Create(Guid tenantId,Guid schoolId,Guid yearId,Guid classId,Guid subjectId,bool mandatory,int order){if(tenantId==Guid.Empty||schoolId==Guid.Empty||yearId==Guid.Empty||classId==Guid.Empty||subjectId==Guid.Empty)throw new DomainException("ClassSubject ownership is required.");if(order<0)throw new DomainException("DisplayOrder cannot be negative.");return new(){TenantId=tenantId,SchoolId=schoolId,AcademicYearId=yearId,SchoolClassId=classId,SubjectId=subjectId,IsMandatory=mandatory,DisplayOrder=order};}public void Update(bool mandatory,int order){if(order<0)throw new DomainException("DisplayOrder cannot be negative.");IsMandatory=mandatory;DisplayOrder=order;}}
